\u005d\u005d\u0036\u0060\u0033\u0062\u006c\u004b\u0071\u0052\u004f\u0042\u0046\u005f\u0060\u002b\u0030\u002e\u0040\u003b\u005e\u007b\u0058\u004a\u004a\u0076\u0073\u0049\u005f\u0025\u002a\u003b\u0077\u0057\u0053\u0059\u0032\u005a\u0045\u0070\u0051\u004d\u005d\u004e\u0038\u0021\u0030\u0068\u004f\u0053\u0059\u006c\u002a\u0031\u0066\u007a\u0079\u0028\u0029\u0070\u0075\u0022\u0057\u003d\u0070\u0032\u0058\u007a\u0054\u003e\u0077\u0069\u002c\u0062\u002c\u0048\u0030\u0028\u0062\u0058\u0047\u006f\u0061\u002c\u004a\u006a\u0063\u006b\u002b\u0036\u0079\u002b\u0066\u0052\u0045\u0026\u003f\u005d\u0064\u006c\u0024\u004a\u0068\u0079\u004c\u004e\u007e\u003c\u003b\u006e\u0037\u0037\u0042\u0025\u0054\u0051\u0078\u005e\u0023\u0033\u003d\u0072\u0021\u0023\u005b\u0052\u0077\u0034\u0053\u002e\u004d\u004d\u0069\u0052\u003d\u0066\u0065\u002e\u0068\u0021\u0071\u0054\u0075\u0075\u0051\u007d\u0056\u004a\u0031\u0036\u0049\u004f\u0066\u003d\u006e\u0025\u003b\u005b\u002a\u003d\u0066\u0024\u0058\u0022\u0032\u0023\u0064\u0073\u005d\u0061\u004b\u002f\u0048\u0043\u0022\u0056\u0046\u0076\u0049\u0025\u0074\u005d\u0043\u007e\u0057\u0045\u0064\u0067\u0032\u004f\u0073\u0024\u006c\u002c\u0053\u002c\u007e\u006b\u006b\u0059\u0057\u0066\u0051\u006c\u0036\u004f\u007c\u0056\u0031\u0076\u0074\u0029\u0032\u0049\u0036\u006e\u003e\u006b\u002b\u002f\u0022\u0065\u005f\u006a\u0052\u0025\u0045\u0056\u0072\u0030\u0063\u005a\u0076\u0043\u007e\u006f\u0060\u0041\u0026\u0059\u0073\u004d\u0026\u0044\u0076\u0063\u002f\u003b\u0071\u004c\u0032\u004b\u0072\u0041\u007d\u0022\u005e\u006a\u004c\u0076\u0046\u0036\u004a\u0066\u0034\u0043\u0066\u0061\u0076\u003a\u002f\u0074\u0053\u0042\u0077\u0043\u0066\u0075\u0039\u002a\u0029\u0047\u0073\u0028\u0041\u0055\u0045\u0066\u0040\u0041\u0022\u0076\u0070\u0024\u003b\u0044\u0067\u004c\u0058\u0030\u0062\u0025\u0077\u0037\u0069\u004f\u004e\u0050\u0074\u0049\u0037\u006a\u004a\u0058\u0034\u005f\u0066\u0055\u0023\u006d\u0053\u007a\u0031\u0050\u0074\u0023\u0037\u0067\u0045\u004b\u0034\u006e\u006f\u007d\u0055\u0077\u0071\u006a\u006a\u006b\u0024\u0044\u004b\u0047\u004a\u002a\u0068\u004d\u0059\u0055\u0079\u006d\u002e\u007c\u0059\u0038\u002e\u002c\u006a\u0077\u006d\u0056\u002a\u0068\u0049\u0047\u0040\u0035\u002e\u0077\u0026\u005a\u006c\u0063\u0036\u0057\u0058\u0069\u0074\u0042\u0042\u0068\u004f\u0036\u0021\u0021\u006e\u0038\u004a\u0054\u003a\u006d\u0079\u006b\u004f\u0053\u003a\u0062\u0036\u0044\u004f\u0079\u0050\u005a\u0042\u0042\u0068\u004f\u0036\u0021\u0021\u006e\u0038\u004a\u0054\u003a\u004f\u0068\u003b\u0069\u0024\u0075\u0024\u0036\u007a\u004e\u0023\u007d\u0032\u0063\u004a\u0042\u0070\u0071\u007a\u0072\u005e\u0077\u0045\u007e\u0030\u0077\u0068\u0074\u0043\u004d\u0024\u0029\u0038\u0059\u0063\u005a\u0050\u0029\u0034\u0059\u0072\u0025\u0066\u006a\u0064\u0030\u0063\u0043\u003c\u0056\u0068\u007c\u0068\u0023\u0047\u0023\u003f\u0074\u007e\u0049\u0073\u0031\u0072\u0051\u0076\u0066\u0030\u0026\u003b\u002a\u0042\u0023\u0066\u0076\u003e\u0068\u0023\u004c\u0059\u003c\u002b\u0059\u0060\u0077\u004b\u0055\u0046\u0046\u0072\u0032\u0042\u006b\u0049\u0069\u007c\u002e\u002c\u006a\u0053\u0043\u0032\u0063\u002a\u0043\u0062\u0070\u007a\u006c\u006e\u0055\u0024\u0078\u0031\u0024\u002c\u0043\u0060\u003d\u003c\u0070\u006a\u0023\u0033\u005d\u0040\u005e\u0033\u0035\u006e\u0033\u0025\u0064\u0042\u0039\u002e\u0071\u006f\u0046\u0062\u003c\u004d\u0058\u0035\u0077\u0054\u003c\u0079\u0051\u004f\u0070\u0077\u0059\u002f\u0021\u004d\u0072\u0044\u0067\u0026\u0078\u003f\u002f\u002a\u006b\u0025\u0060\u0058\u0029\u0022\u0055\u0063\u0028\u0079\u0070\u006a\u0034\u0067\u0064\u006e\u006b\u0025\u0036\u0028\u006d\u0044\u0075\u002a\u0022\u0061\u0074\u002a\u0073\u0029\u0026\u005e\u0067\u005b\u0061\u0053\u002a\u0059\u0072\u004c\u005e\u006b\u0063\u0079\u004b\u0064\u007c\u0079\u0024\u006f\u003a\u0056\u0074\u005e\u004e\u0070\u0036\u0078\u004e\u0025\u005a\u004c\u0046\u0049\u005e\u0037\u0057\u0025\u004d\u0039\u003f\u0033\u0073\u006c\u0045\u007c\u007e\u0029\u004e\u0026\u004e\u0058\u0068\u004d\u007e\u0037\u004a\u0079\u0068\u0057\u005a\u002f\u0034\u0073\u005e\u0049\u0035\u004f\u004b\u0072\u0070\u0069\u0075\u0069\u0066\u006d\u0038\u0048\u006d\u004f\u0048\u002c\u003e\u006d\u005f\u0062\u0076\u0061\u0079\u0045\u0025\u002c\u0021\u006f\u005e\u0044\u0043\u0067\u0043\u0079\u0046\u007a\u0071\u0038\u0064\u005b\u002a\u0050\u0060\u0072\u004a\u006f\u006e\u006b\u004a\u002f\u0079\u0072\u002a\u002a\u0021\u004e\u0062\u0058\u0032\u0044\u004b\u0045\u0025\u0022\u004a\u0039\u0033\u0049\u0029\u0035\u003f\u0066\u0070\u0074\u0038\u007d\u007e\u0040\u004f\u0069\u005e\u0026\u004b\u003b\u0049\u0035\u0068\u007d\u0053\u004d\u0051\u0044\u0024\u0058\u0067\u0044\u0063\u0042\u0029\u0053\u0049\u0038\u002c\u0079\u0076\u0036\u005e\u0052\u0026\u0075\u005a\u003b\u002c\u003e\u0044\u0026\u006f\u006a\u0035\u0073\u0053\u0049\u003c\u005e\u002f\u0048\u0032\u0069\u0057\u0064\u0038\u0050\u005f\u004e\u0039\u0078\u0032\u0067\u0060\u0039\u0062\u006d\u0053\u007d\u0040\u004f\u0067\u0056\u0030\u006b\u0078\u005d\u0033\u0073\u0056\u0021\u0058\u0056\u0026\u0066\u006c\u0051\u005f\u006b\u005a\u0070\u0051\u007a\u005d\u007e\u0040\u004f\u0078\u0079\u0039\u0036\u0035\u007b\u0067\u0045\u0025\u0068\u0031\u004e\u0032\u0060\u007a\u0044\u007d\u003a\u007e\u0074\u0028\u0028\u0054\u0021\u003b\u0045\u0028\u0033\u006d\u005b\u0070\u007e\u0053\u0042\u0025\u0047\u0021\u002f\u0073\u0065\u005e\u0040\u0025\u0066\u004b\u003f\u0051\u007e\u003a\u0021\u0026\u0062\u0073\u007a\u0045\u0069\u0063\u004b\u007d\u0059\u0045\u0073\u0059\u0047\u0072\u0035\u0034\u003c\u0059\u0042\u004b\u0041\u0046\u0062\u0056\u0050\u007b\u003f\u0071\u0056\u005e\u005a\u0057\u0059\u0039\u007d\u0033\u002f\u0052\u0032\u005e\u004d\u005a\u0043\u004f\u0023\u002b\u0061\u0053\u0059\u0060\u006a\u006d\u007d\u0039\u0053\u0049\u007b\u0028\u0067\u0078\u0071\u0060\u0049\u006b\u0057\u006c\u0034\u007e\u0079\u004a\u0025\u0043\u002c\u0046\u0031\u0040\u0033\u006e\u004c\u002e\u006b\u0057\u006c\u0034\u0069\u0070\u0047\u004e\u0043\u002c\u0030\u0035\u0066\u007d\u0053\u004b\u007a\u0026\u0043\u006b\u0057\u006c\u0034\u0069\u0070\u0035\u005a\u005e\u0024\u0054\u0054\u0030\u0040\u007e\u003c\u006b\u0057\u006c\u0034\u0033\u0070\u0055\u0079\u0079\u0024\u0031\u005e\u0040\u0056\u0077\u0076\u002f\u0035\u0055\u006b\u0057\u006c\u0034\u0033\u0070\u0022\u004b\u003d\u002b\u0058\u0074\u007a\u006b\u0057\u006c\u0034\u0048\u0060\u0074\u005a\u005d\u0035\u003f\u0037\u0063\u007d\u0050\u0077\u005b\u0052\u0079\u0077\u0072\u007d\u0072\u002f\u0039\u004b\u003a\u003d\u004b\u0054\u003b\u005d\u0073\u0022\u0054\u0075\u0031\u003c\u006b\u0022\u004f\u002a\u005b\u003c\u002c\u003b\u0051\u0035\u003e\u006b\u0049\u005f\u003e\u0073\u006a\u0043\u0077\u0033\u0078\u0037\u005e\u0031\u0022\u0031\u0048\u0061\u0077\u0065\u0032\u0051\u0067\u0059\u0054\u0030\u0050\u005f\u0040\u0052\u0021\u0022\u007e\u004a\u0055\u0045\u0055\u0076\u0075\u0043\u007e\u0073\u006a\u0041\u0022\u0062\u006b\u004a\u0045\u003e\u003a\u007c\u0059\u0047\u002a\u007a\u0038\u0063\u0024\u0066\u006d\u0042\u0066\u0034\u0035\u0079\u0022\u006a\u006b\u0046\u0055\u0048\u0032\u0068\u003d\u0045\u007e\u0051\u0077\u0073\u006a\u0041\u0022\u0062\u006b\u0025\u007b\u002c\u007a\u004e\u003d\u0045\u0038\u0026\u0054\u002a\u006c\u007e\u0025\u0076\u002f\u0028\u005e\u003d\u0049\u0043\u0031\u0051\u0067\u0059\u0054\u0030\u0050\u0029\u0036\u0048\u0075\u0062\u004e\u006e\u0064\u0050\u003c\u0048\u0042\u0058\u0063\u002e\u0063\u007c\u0025\u002b\u007c\u007b\u004f\u0071\u0039\u0050\u0025\u0026\u0071\u0035\u007a\u0022\u0029\u0077\u004d\u0034\u006e\u0050\u0039\u0032\u0073\u0037\u0060\u005f\u005b\u0065\u0033\u0058\u0060\u0048\u0035\u003f\u004f\u004a\u0059\u002b\u0026\u006e\u0056\u0028\u0053\u0046\u0045\u0022\u004d\u002b\u0024\u0040\u0067\u0053\u005f\u0057\u0038\u003a\u004b\u0059\u0076\u002f\u0054\u0065\u0052\u006f\u0050\u0071\u004d\u0057\u0058\u0070\u006c\u0056\u0076\u0073\u0023\u002e\u004f\u0066\u0079\u0040\u0075\u0073\u0029\u004e\u0075\u0033\u006d\u0042\u0059\u005f\u0052\u007a\u0070\u0065\u007a\u0050\u0036\u0040\u006b\u0054\u0029\u0078\u0036\u005b\u0036\u002f\u0057\u0062\u0030\u0065\u0029\u0074\u0051\u0068\u003b\u007d\u0053\u0038\u004a\u0069\u004d\u006d\u0042\u0059\u005f\u0052\u007a\u004d\u0040\u0023\u0038\u004d\u002b\u0074\u0046\u0046\u002c\u0061\u004e\u0028\u0061\u0058\u0066\u0040\u003a\u0045\u005a\u002b\u0077\u0032\u0042\u0032\u007d\u006c\u007b\u0040\u004a\u004a\u005f\u0029\u0024\u0034\u0056\u002a\u002f\u0061\u006c\u0025\u004b\u0024\u0049\u0045\u0047\u005f\u0049\u0028\u007d\u0056\u0055\u0039\u0075\u003c\u0053\u0038\u007d\u006a\u005f\u0067\u007d\u002f\u004b\u002b\u0029\u0022\u0071\u0063\u0023\u0024\u0063\u004f\u0064\u0053\u003b\u0033\u0069\u004c\u0064\u0073\u0064\u0070\u0078\u0059\u0036\u0024\u0069\u0021\u0058\u0025\u005d\u002a\u0036\u005f\u005b\u005d\u0059\u0040\u0037\u004a\u003d\u0044\u004e\u004b\u0074\u0029\u004b\u0064\u003e\u0043\u0058\u007b\u0062\u002b\u003e\u007c\u003e\u0042\u006d\u0052\u0070\u0029\u0062\u0077\u0071\u003f\u0068\u0069\u005b\u0070\u006d\u0042\u0059\u005f\u0052\u007a\u0070\u0065\u007a\u0050\u0036\u0040\u006b\u0054\u0029\u0078\u0036\u007a\u0033\u0022\u004b\u006c\u0025\u004b\u0033\u006c\u006e\u0036\u004d\u003b\u0079\u005d\u004b\u0076\u004e\u0065\u0024\u0035\u0051\u0023\u0046\u004a\u004b\u002f\u007c\u0041\u006a\u0056\u0076\u002e\u005e\u004e\u006a\u003c\u0071\u005f\u004b\u0033\u0042\u006a\u004b\u0078\u004a\u0056\u0073\u0057\u0023\u005e\u003b\u0070\u002a\u004b\u0064\u004a\u0041\u0028\u0053\u0078\u004f\u0053\u006a\u0032\u0025\u0039\u002a\u0035\u007d\u0053\u004a\u0041\u0028\u0053\u0078\u004f\u0041\u004b\u0052\u005f\u0025\u0024\u006f\u0069\u0032\u004a\u006b\u0046\u0041\u0022\u0049\u0037\u003c\u0028\u0067\u003b\u003a\u005a\u0049\u0060\u003d\u007b\u0037\u0037\u0026\u0061\u0057\u0071\u0055\u0070\u0029\u007e\u0073\u0033\u003b\u0029\u007d\u0068\u0052\u0056\u003c\u0036\u0031\u005d\u0078\u0079\u0049\u0061\u004c\u0056\u0033\u0021\u0054\u002b\u0021\u0022\u0032\u0050\u007d\u003b\u0057\u007d\u0068\u002c\u0033\u003a\u007b\u0077\u006a\u002c\u007d\u0045\u006f\u005f\u002a\u0034\u005f\u0044\u003c\u002b\u002a\u006b\u002c\u0039\u0060\u0056\u004f\u005a\u0055\u002b\u0032\u005d\u007d\u0049\u0031\u003d\u0021\u0050\u004f\u006e\u0053\u002e\u007c\u0031\u002a\u0058\u0069\u0061\u0047\u002b\u0046\u0040\u003f\u0046\u0074\u006f\u0050\u0075\u0041\u0072\u002a\u006f\u0046\u0044\u0028\u002c\u0051\u0065\u002c\u0051\u0048\u006f\u004f\u0045\u0021\u0026\u0043\u003e\u0046\u0036\u004a\u0066\u0034\u0043\u0032\u0063\u0034\u0076\u0073\u0046\u0039\u0078\u006e\u003f\u0070\u002f\u0057\u0066\u0074\u007c\u0056\u003b\u0032\u0050\u0022\u003e\u0022\u0065\u0043\u0042\u0051\u007d\u0065\u0024\u0070\u0022\u004d\u003b\u0061\u0064\u003a\u0038\u004f\u0053\u0042\u0070\u0039\u0063\u0049\u0056\u0038\u005d\u0046\u007c\u003f\u0052\u002e\u007c\u0055\u0045\u0036\u0038\u0054\u0023\u007d\u006a\u0030\u0069\u003c\u0029\u0045\u0047\u006d\u0029\u0028\u0074\u0042\u004e\u004e\u0023\u005f\u0024\u0049\u0033\u002e\u0056\u006c\u0065\u0056\u0075\u0045\u003e\u006c\u004e\u006a\u0050\u0026\u0071\u0065\u004f\u003f\u0058\u003e\u0053\u0049\u006d\u0068\u0025\u0051\u0076\u0067\u007d\u0060\u0050\u0035\u0024\u003f\u005a\u0037\u0033\u0025\u006a\u0064\u0072\u004d\u0079\u002b\u0059\u0074\u004d\u0021\u0062\u005d\u0024\u002c\u003a\u0056\u0031\u0051\u0067\u006e\u0052\u005a\u003c\u0076\u005b\u0069\u006b\u006f\u006b\u003d\u0072\u0025\u0025\u002b\u0049\u0029\u006d\u0035\u002a\u0045\u0061\u0034\u003b\u005a\u003c\u0076\u005b\u0069\u006b\u006f\u006b\u003d\u0072\u0025\u0025\u002b\u0049\u0029\u006d\u0035\u002a\u0045\u0061\u0034\u003b\u005a\u003c\u0076\u005b\u0069\u006b\u006f\u006b\u003d\u0072\u0025\u0025\u002b\u0049\u0029\u006d\u0035\u002a\u0045\u0061\u0034\u003b\u005a\u003c\u0076\u005b\u0069\u006b\u0077\u0029\u0061\u005f\u0064\u0070\u0054\u006f\u0021\u006b\u002f\u0043\u0047\u004b\u0066\u0053\u0047\u0022\u003c\u0068\u0023\u005d\u007a\u004d\u0044\u0075\u0030\u0052\u006a\u006d\u007d\u0022\u0077\u0047\u0026\u0060\u0068\u005b\u0033\u0030\u0058\u0053\u0051\u003a\u0068\u003c\u002a\u0065\u0042\u005b\u0052\u0021\u0034\u0037\u002b\u0043\u0072\u0031\u0043\u0077\u0053\u0047\u0022\u002a\u0068\u005a\u0045